/**
 * Installable application (step 11): iOS splash screens generated by
 * `scripts/brand/generate-icons.mjs` in `public/splash/`. No service worker at this step
 * (see docs/pwa.md).
 */

/** iPad screens in CSS pixels (portrait) with their pixel ratio. */
export const IPAD_SCREENS = [
  { width: 768, height: 1024, ratio: 2 },
  { width: 810, height: 1080, ratio: 2 },
  { width: 820, height: 1180, ratio: 2 },
  { width: 834, height: 1194, ratio: 2 },
  { width: 1024, height: 1366, ratio: 2 },
] as const;

/** One `apple-touch-startup-image` link: file and media query. */
export interface StartupImage {
  url: string;
  media: string;
}

/** Splash screens of every iPad screen, portrait and landscape. */
export function startupImages(): StartupImage[] {
  return IPAD_SCREENS.flatMap(({ width, height, ratio }) => {
    const base = `(device-width: ${width}px) and (device-height: ${height}px) and (-webkit-device-pixel-ratio: ${ratio})`;
    const w = width * ratio;
    const h = height * ratio;
    return [
      { url: `/splash/ipad-${w}x${h}.png`, media: `${base} and (orientation: portrait)` },
      { url: `/splash/ipad-${h}x${w}.png`, media: `${base} and (orientation: landscape)` },
    ];
  });
}
